function nextBiggerOnRing(nums: number[]): number[] {
  const n = nums.length, ans = new Array(n).fill(-1);
  for (let i = 0; i < n; i++) {
    for (let step = 1; step < n; step++) {
      const v = nums[(i + step) % n];
      if (v > nums[i]) { ans[i] = v; break; }
    }
  }
  return ans;
}

