function nextBiggerOnRing(nums: number[]): number[] {
  const n = nums.length, ans = new Array(n).fill(-1);
  const stack: number[] = []; // indexes, values decreasing bottom to top
  for (let k = 0; k < 2 * n; k++) {
    const i = k % n;
    while (stack.length && nums[stack[stack.length - 1]] < nums[i]) ans[stack.pop()!] = nums[i];
    if (k < n) stack.push(i);
  }
  return ans;
}

